from datetime import date; from pathlib import Path; from unittest.mock import AsyncMock; from uuid import uuid4; import pytest; from src.extraction import DocumentSource; from src.extraction.extension.prompts.statement import get_parsing_prompt; from src.extraction.extension.service import ExtractionError, ExtractionService, _tolerant_parse_date
def test_AC13_19_4_parsing_prompt_instructs_iso_date_normalization(): 'AC-extraction.119.4'; prompt = get_parsing_prompt('DBS'); assert 'Normalize EVERY date to ISO YYYY-MM-DD' in prompt; assert 'never echo a non-ISO source format' in prompt; assert '2025年01月15日 -> 2025-01-15' in prompt
def test_AC13_19_1_tolerant_parse_date_accepts_non_iso_formats(): 'AC-extraction.119.1'; assert _tolerant_parse_date('2025-01-15') == date(2025, 1, 15); assert _tolerant_parse_date('2025/01/15') == date(2025, 1, 15); assert _tolerant_parse_date('2025.01.15') == date(2025, 1, 15); assert _tolerant_parse_date('2025年01月15日') == date(2025, 1, 15); assert _tolerant_parse_date('15/01/2025') == date(2025, 1, 15); assert _tolerant_parse_date('15 Jan 2025') == date(2025, 1, 15); assert _tolerant_parse_date('2025-01-15T00:00:00') == date(2025, 1, 15); assert all((_tolerant_parse_date(bad) is None for bad in (None, '', '   ', 'None', 'null', 'n/a', '-', 'not-a-date')))
async def test_AC13_19_2_chinese_format_statement_parses_instead_of_aborting(): 'AC-extraction.119.2'; service = ExtractionService(); service.extract_financial_data = AsyncMock(return_value={'period_start': '2025年01月01日', 'period_end': '2025年01月31日', 'currency': 'CNY', 'opening_balance': '100.00', 'closing_balance': '150.00', 'transactions': [{'date': '2025年01月15日', 'amount': '50.00', 'direction': 'IN', 'description': '工资'}]}); result = await service.parse_document(DocumentSource.resolve(path=Path('zh.pdf'), content=b'content'), institution='CMB', user_id=uuid4()); assert result.period_start == date(2025, 1, 1); assert result.period_end == date(2025, 1, 31); assert len(result.transactions) == 1; assert result.transactions[0].transaction_date == date(2025, 1, 15)
async def test_AC13_19_3_one_bad_row_date_is_quarantined():
    'AC-extraction.119.3'; service = ExtractionService(); service.extract_financial_data = AsyncMock(return_value={'period_start': '2025-01-01', 'period_end': '2025-01-31', 'currency': 'SGD', 'opening_balance': '100.00', 'closing_balance': '150.00', 'transactions': [{'date': 'garbage-date', 'amount': '10.00', 'direction': 'IN', 'description': 'Bad'}, {'date': '2025/01/20', 'amount': '50.00', 'direction': 'IN', 'description': 'Good'}]})
    with pytest.raises(ExtractionError, match='Transaction date'): await service.parse_document(DocumentSource.resolve(path=Path('mixed.pdf'), content=b'content'), institution='DBS', user_id=uuid4())
